<?php
declare(strict_types=1);require_once __DIR__.'/includes/admin_auth.php';require_once __DIR__.'/includes/csrf.php';require_once __DIR__.'/connection.php';$message='';$type='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');if($title===''){$message='Survey title is required.';$type='danger';}else{$stmt=mysqli_prepare($connection,'INSERT INTO surveys(title,description,active) VALUES(?,?,1)');mysqli_stmt_bind_param($stmt,'ss',$title,$description);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$message='Survey created.';$type='success';}}$surveys=[];$r=mysqli_query($connection,'SELECT s.*,COUNT(q.id) questions FROM surveys s LEFT JOIN survey_questions q ON q.survey_id=s.id GROUP BY s.id ORDER BY s.id DESC');if($r)while($row=mysqli_fetch_assoc($r))$surveys[]=$row;?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Surveys | AlumTrace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/alumtrace.css"></head><body><?php require __DIR__.'/includes/sidebar.php';?><div class="main-wrapper"><?php require __DIR__.'/includes/topbar.php';?><main class="content"><div class="page-head"><h2>Manage Surveys</h2><p>Create tracer surveys that alumni can answer.</p></div><?php if($message):?><div class="alert alert-<?=$type?>"><?=htmlspecialchars($message)?></div><?php endif;?><div class="admin-split"><div class="panel"><h2>Existing surveys</h2><?php foreach($surveys as $s):?><article class="record-card"><h3><?=htmlspecialchars($s['title'])?></h3><p><?=htmlspecialchars($s['description']??'')?></p><span class="tag"><?=htmlspecialchars($s['questions'])?> questions</span></article><?php endforeach;if(!$surveys):?><p class="muted">No surveys yet.</p><?php endif;?></div><div class="panel"><h2>Create survey</h2><form method="post"><?=csrf_field()?><div class="field"><label>Title</label><input class="input" name="title" required></div><div class="field"><label>Description</label><textarea class="textarea" name="description"></textarea></div><button class="btn btn-primary" type="submit">Create survey</button></form></div></div></main><?php require __DIR__.'/includes/dashboard-footer.php';?></div><script src="assets/js/alumtrace.js"></script></body></html>
